// Wandle jede heruntergeladene Binary in einen Anthropic-Image-Content-Block um.
// n8n speichert Binary-Data bereits als base64-String → wir können sie direkt verwenden.
return $input.all().map(item => {
  const bin = (item.binary && item.binary.data) || {};
  return {
    json: {
      image_block: {
        type: 'image',
        source: {
          type: 'base64',
          media_type: bin.mimeType || 'image/jpeg',
          data: bin.data || ''
        }
      }
    }
  };
});

// Baut den vollständigen Anthropic-Messages-Request zusammen.
// - images: 0..n Image-Blocks aus dem TRUE-Pfad (oder [] aus dem FALSE-Pfad)
// - Beobachtungs-Kontext aus dem Webhook-Body
const images = $json.images || [];
const webhook = $('Webhook: Airtable Automation').first().json.body || {};
const fields  = webhook.fields || {};

const hasImages = images.length > 0;
const text = `Du bist ein Lean-Experte und EHS-Beauftragter. Analysiere die folgende Gemba-Walk-Beobachtung${
  hasImages
    ? ` zusammen mit den ${images.length} beigefügten Foto(s)`
    : ' ausschließlich anhand des Textes (es liegen keine Fotos vor)'
}.

Beobachtung: ${fields['Waste Observation Name'] || 'Unbenannt'}
Ort: ${fields.Location || 'unbekannt'}
Waste Type: ${fields['Waste Type'] || 'unbekannt'}
Impact: ${fields.Impact || 'unbekannt'}
Priorität (gemeldet): ${fields.Priority || 'unbekannt'}
EHS Concern: ${fields['EHS Concern'] ? 'ja' : 'nein'}
EHS Focus: ${fields['EHS Focus'] || 'n/a'}
Beschreibung / Notes: ${fields['Description / Notes'] || ''}
Beobachter: ${fields.Observer || 'unbekannt'}

Identifiziere das Problem, die wahrscheinliche Ursache (5-Why / Ishikawa) und schlage 1-3 konkrete Maßnahmen mit Rollen als Verantwortliche vor.

Antworte AUSSCHLIESSLICH als gültiges JSON in genau diesem Schema (keine Markdown-Fences, kein Fließtext):
{
  "ai_analysis": "Strukturierte Analyse inkl. erkennbarer EHS-/Lean-Themen (max. 600 Zeichen)",
  "root_cause": "Vermutete Grundursache (eine Zeile)",
  "solution_approach": "Empfohlener Lösungsansatz (max. 400 Zeichen)",
  "priority": "Low|Middle|High",
  "actions": [
    {
      "description": "Konkrete Handlung (SMART formuliert)",
      "notes": "Hintergrund / Umsetzungshinweis",
      "owner_role": "Rolle EXAKT aus folgender Liste (muss mit dem Feld 'Role' in der Users-Tabelle übereinstimmen): Shopfloor-Leiter | EHS-Manager | Instandhaltung | Lagerleitung | Qualitätsmanagement",
      "deliverable_days": 7
    }
  ]
}`;

const content = [...images, { type: 'text', text }];

return [{
  json: {
    body: {
      model: 'claude-opus-4-6',
      max_tokens: 1500,
      messages: [{ role: 'user', content }]
    }
  }
}];

// Parsed Claude-Response → flache Felder für die nachfolgenden Nodes.
const item = $input.first().json;
const raw  = (item.content && item.content[0] && item.content[0].text) || '';

let parsed;
try {
  // Markdown-Fences vorsichtshalber entfernen
  const cleaned = raw.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch (err) {
  throw new Error('Claude hat kein gültiges JSON geliefert: ' + raw);
}

return [{
  json: {
    ai_analysis: parsed.ai_analysis || '',
    root_cause: parsed.root_cause || '',
    solution_approach: parsed.solution_approach || '',
    priority: parsed.priority || 'Middle',
    actions: Array.isArray(parsed.actions) ? parsed.actions : []
  }
}];
